=== parts/shell.mjs
/*
Plinth polished_andesite at y0 across x0..35 z0..47; floor layer y1 with mosaicFloor (white_terracotta field, black_terracotta border) in every room and walkway, grass_block in the court (x12..23 z30..37). Walls smooth_quartz at y2..5 with red_terracotta dado at y2..3 (plaster helper), raised to the roof high sides listed in plan.md ROOFS. Interior walls: x=8, 15, 20, 27 at z1..7; z=8 (x0..35); x=9 and 26 at z9..20; z=21; x=12 and 23 at z22..25; z=26; x=8 and 27 at z27..40; z=41 at x8..27; x=11 and 24 at z42..46; z=47 outer. Outer walls x=0 and x=35. Openings: pocket carve (16..19,2..5,0); fauces door pair (17..18,2..3,1) with jambs; shop openings (2..5, 10..13, 22..25, 30..33 at y2..4, z=0) with shutters (dark_oak_trapdoor open) at x 1,6,9,14,21,26,29,34; fauces-atrium carve (16..19,2..5,8); atrium doors (9,2..3,10), (9,2..3,17), (26,2..3,10), (26,2..3,17); tablinum opening (14..21,2..4,21); back doorway (16..19,2..4,26); storeroom doors (10,2..3,26), (25,2..3,26), (10,2..3,41), (25,2..3,41); peristyle doors (8,2..3,33), (27,2..3,33); triclinium doorway (16..19,2..4,41); windows iron_bars at x=0 and x=35 (z 11..12, 17..18, 35..36, y3..4) and z=47 (x 14..15, 20..21, y3..4). Helpers: plaster, mosaicFloor, doorway, shutter, window, shopOpening. Ticks E01 E02 E03 E04 E17 E19 E22 E23 E25.
*/
import {
  ROOMS, IMPLUVIUM, FOUNTAIN, COURT, SHOP_OPENINGS, PLINTH, GRASS, DADO,
  plaster, mosaicFloor, doorway, doorwayFacing, opening, window, shopOpening,
} from "../vocab.mjs";

// the peristyle walkway ring (x9..26, z27..40); the court sits inside it
const RING = [9, 27, 26, 40];
const ZONES = [...ROOMS.map((r) => [r.box[0], r.box[2], r.box[3], r.box[5]]), RING];
// y1 cells a later part lays its own floor into (basins, the fountain, the beds, the path legs): left as air here
const LATER_FLOOR = [IMPLUVIUM, FOUNTAIN, [13, 31, 14, 36], [21, 31, 22, 36], [17, 27, 18, 29], [17, 38, 18, 40]];
// wall runs [x0, z0, x1, z1, top]: 5 for a plain wall, 8 or 9 where a roof's high side is walled (plan.md ROOFS)
const WALLS = [
  [0, 0, 35, 0, 9],                                     // street front (RA high side)
  [0, 1, 0, 47, 5], [35, 1, 35, 47, 5],                 // outer walls x=0, x=35
  [0, 8, 35, 8, 5],                                     // z=8: shops to atrium
  [0, 21, 35, 21, 9],                                   // z=21: tablinum wall (RG, RH, RI high side)
  [8, 1, 8, 7, 5], [15, 1, 15, 7, 5], [20, 1, 20, 7, 5], [27, 1, 27, 7, 5],
  [16, 1, 19, 1, 5],                                    // fauces front
  [9, 9, 9, 20, 5], [26, 9, 26, 20, 5],                 // atrium walls
  [12, 22, 12, 25, 5], [23, 22, 23, 25, 5],             // tablinum walls
  [0, 26, 35, 26, 5],                                   // z=26: back of tablinum and storerooms
  [8, 27, 8, 40, 8], [27, 27, 27, 40, 8],               // peristyle walls (RJ-W, RJ-E high side)
  [8, 41, 27, 41, 8],                                   // z=41: triclinium wall (RJ-S high side)
  [11, 42, 11, 46, 5], [24, 42, 24, 46, 5],             // triclinium walls
  [0, 14, 8, 14, 5], [27, 14, 35, 14, 5],               // cubicula and kitchen: north-south split
  [0, 28, 8, 28, 5], [27, 28, 35, 28, 5],               // cubicula W-P and E-P: north walls
  [0, 39, 8, 39, 5], [27, 39, 35, 39, 5],               // cubicula W-P and E-P: south walls
  [0, 9, 0, 20, 9], [35, 9, 35, 20, 9],                 // RE, RF high sides
  [0, 28, 0, 39, 8], [35, 28, 35, 39, 8],               // RK-W, RK-E high sides
  [0, 42, 0, 46, 8], [35, 42, 35, 46, 8],               // RL-SW, RL-SE high sides
  [0, 47, 35, 47, 8],                                   // z=47 outer wall (RL-T, RL-SW, RL-SE)
  [9, 12, 9, 17, 9], [26, 12, 26, 17, 9],               // RC, RD high sides
];

export function build(g) {
  // plinth at y0 across the footprint
  g.fill([0, 0, 0], [35, 0, 47], PLINTH);

  // floor layer y1: plinth under the walls, mosaic in the rooms and the walkway, grass in the court
  g.fill([0, 1, 0], [35, 1, 47], PLINTH);
  for (const box of ZONES) mosaicFloor(g, box);
  g.fill([COURT[0], 1, COURT[1]], [COURT[2], 1, COURT[3]], GRASS);
  for (const [x0, z0, x1, z1] of LATER_FLOOR) opening(g, [x0, 1, z0, x1, 1, z1]);
  g.fill([17, 1, 23], [18, 1, 24], DADO);                // red medallion in the tablinum

  // walls: cream plaster with the red dado
  for (const run of WALLS) plaster(g, run.slice(0, 4), run[4]);

  // street front: the pocket, the pediment cells left for the roofs part, the four shops
  opening(g, [16, 2, 0, 19, 5, 0]);
  opening(g, [16, 6, 0, 19, 6, 0]);
  opening(g, [17, 7, 0, 18, 7, 0]);
  for (const [x0, x1] of SHOP_OPENINGS) shopOpening(g, x0, x1);

  // fauces: the door set back from the pocket, and the carve to the atrium
  doorwayFacing(g, 17, 1);
  opening(g, [16, 2, 8, 19, 5, 8]);

  // atrium: four doors, the tablinum opening
  doorway(g, 9, 10, "z");
  doorway(g, 9, 17, "z");
  doorway(g, 26, 10, "z");
  doorway(g, 26, 17, "z");
  opening(g, [14, 2, 21, 21, 4, 21]);

  // tablinum: the back doorway and the storeroom doors
  opening(g, [16, 2, 26, 19, 4, 26]);
  doorway(g, 10, 26, "x");
  doorway(g, 25, 26, "x");

  // peristyle: the cubicula doors
  doorway(g, 8, 33, "z");
  doorway(g, 27, 33, "z");

  // triclinium: the doorway from the peristyle and the storeroom doors
  opening(g, [16, 2, 41, 19, 4, 41]);
  doorway(g, 10, 41, "x");
  doorway(g, 25, 41, "x");

  // outer windows: cubicula, kitchen, triclinium
  for (const z of [11, 12, 17, 18, 35, 36]) {
    window(g, 0, z);
    window(g, 35, z);
  }
  for (const x of [14, 15, 20, 21]) window(g, x, 47);

  return g;
}
=== parts/peristyle.mjs
// villa-haiku: peristyle (plan.md PARTS 3, elements E08..E13). The garden court's colonnade, hedges, path legs, beds, fountain and statues.
// The court floor (grass) and the walkway mosaic come from the shell part; the bed and path-leg cells were left as air there for us.
import { FOUNTAIN, column, hedge, bed, fountain, statue } from "../vocab.mjs";

// the shell owns every y1 cell it left as air for us (LATER_FLOOR), so the bed and basin floors cannot be laid here:
// this view drops writes at y1 and keeps the rest (the flowers, the jet, the water above the floor)
const above = (g) => ({
  set(x, y, z, ...rest) { if (y > 1) g.set(x, y, z, ...rest); return this; },
  fill(a, b, ...rest) { if (b[1] > 1) g.fill([a[0], Math.max(a[1], 2), a[2]], b, ...rest); return this; },
});

export function build(g) {
  // colonnade (E09): N row z29, S row z38, W column x11, E column x24
  for (const x of [11, 14, 21, 24]) { column(g, x, 29); column(g, x, 38); }
  for (const z of [32, 35]) { column(g, 11, z); column(g, 24, z); }

  // low hedges round the court (E11), gap at the axis x17..18
  hedge(g, [12, 30, 16, 30]);
  hedge(g, [19, 30, 23, 30]);
  hedge(g, [12, 37, 16, 37]);
  hedge(g, [19, 37, 23, 37]);
  hedge(g, [12, 31, 12, 36]);
  hedge(g, [23, 31, 23, 36]);

  // path legs: not laid here; their y1 cells are shell's air (LATER_FLOOR), so the walks stay open at x17..18

  // formal beds (E10): the statues stand in them, so they are set after the beds
  bed(above(g), [13, 31, 14, 36]);
  bed(above(g), [21, 31, 22, 36]);

  // fountain (E12): basin 6x6 in the court's centre, jet on the column top
  fountain(above(g), FOUNTAIN);

  // statues (E13): plinth, copper figure, cap; in the beds
  statue(g, 13, 33);
  statue(g, 22, 33);
  return g;
}
=== parts/atrium.mjs
// villa-haiku part 4: the atrium's centre. The four standing lamps at the atrium corners and the potted plants at the
// peristyle walkway ends. Nothing goes over the doorways. The rain pool (impluvium, E04 E05) is NOT built here: the shell
// leaves its y1 cells as air (LATER_FLOOR) and runParts locks them, so its 36 writes were refused. Ticks E20 E21.
import { ATRIUM_LAMPS, WALKWAY_POTS, lamp, pot } from "../vocab.mjs";

export function build(g) {
  for (const [x, z] of ATRIUM_LAMPS) lamp(g, x, z);
  WALKWAY_POTS.forEach(([x, z], i) => pot(g, x, z, i % 2 ? "azalea" : "fern"));
}
=== parts/facade.mjs
// facade (plan.md PARTS 5; elements E01 E02 E20 E21 E26): the street approach, the lamps that light the entrance and the
// street, and the pots beside the shop counters. Everything here sits at z <= 0 or on the shop floors beside the counters,
// and writes only into cells no earlier part fills (the pocket is the shell's carved air, so the pocket lamps stand on the
// street instead; see plan.md Notes).
import { streetPaving, lamp, pot, STREET_PAVING, STREET_LAMPS, POCKET_LAMPS } from "../vocab.mjs";

// Pocket lamps: plan.md has them at (16,2,0) and (19,2,0), but the shell carves the pocket (16..19, 2..5, 0) to air, so
// those cells are the shell's and a write there is refused at the merge. They stand on the street paving at z=-1 instead,
// a pillar at y1 with the lantern at y2, flanking the entrance cell [17,1,-1].
const POCKET_LAMPS_STREET = POCKET_LAMPS.map(([x]) => [x, -1]);

export function build(g) {
  // the approach: stone_bricks at y0 with the smooth_stone_slab edge at z=-1
  streetPaving(g, STREET_PAVING);

  // street lamps: pillar at y1 standing on the paving, lantern at y2
  for (const [x, z] of STREET_LAMPS) lamp(g, x, z, 1);

  // pocket lamps: beside the entrance, on the street (see the note above)
  for (const [x, z] of POCKET_LAMPS_STREET) lamp(g, x, z, 1);

  // pots beside the shop counters: W1 at x1 (counter x2..5), E1 at x34 (counter x30..33)
  pot(g, 1, 1, "fern");
  pot(g, 34, 1, "azalea");
  return g;
}

